'use strict';
const $ = id => document.getElementById(id);
// Escapado, catálogo de materiales y captura rápida por Enter adaptados de METales-GV V15.
const esc = s => String(s ?? '').replace(/[&<>"']/g, m => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#039;' }[m]));
const money = cents => new Intl.NumberFormat('es-MX', { style:'currency', currency:'MXN' }).format((cents || 0) / 100);
const number = (n, digits=3) => new Intl.NumberFormat('es-MX', { minimumFractionDigits:digits, maximumFractionDigits:digits }).format(n);
const kg = g => number((g || 0) / 1000);
const amount = n => ((n || 0) / 100).toFixed(2);
const weight = n => ((n || 0) / 1000).toFixed(3);
const payments = { cash:'Efectivo MXN', transfer:'Transferencia', card:'Tarjeta', usd:'Efectivo USD' };
const roles = { admin:'Administrador', cashier:'Cajero', viewer:'Consulta' };
const types = { purchase:'Compra', sale:'Venta', expense:'Gasto', entry:'Entrada', withdrawal:'Retiro', void:'Cancelación', opening:'Inicial', adjustment:'Ajuste', legacy:'Importación' };
const common = ['Cartón','Cartón de primera','Cartón de segunda','PET','PET cristal','PET verde','Aluminio','Lata de aluminio','Fierro','Cobre','Cobre brillante','Cobre mixto','Bronce','Archivo','Papel','Periódico','Plástico','Chatarra'];
const icons = { Fierro:'▧', Cobre:'◉', 'Cobre brillante':'◈', 'Cobre mixto':'◉', Bronce:'◆', Aluminio:'▱', 'Lata de aluminio':'▱', Chatarra:'⚙', PET:'♧', Cartón:'▣', Papel:'▤' };
const modules = [
 ['inicio','Resumen','◫','Tu negocio, en claro.'], ['compras','Compras','↙','Recibe materiales, registra kilos y paga al proveedor.'],
 ['ventas','Ventas','↗','Vende por kilogramo con existencias verificadas.'], ['inventario','Inventario','▦','Existencias, costo promedio y trazabilidad de cada movimiento.'],
 ['caja','Caja y turnos','▣','Controla tu efectivo en MXN y USD, desde la apertura hasta el corte.'], ['gastos','Gastos','↘','Registra los gastos de tu operación.'],
 ['tickets','Tickets','▤','Consulta y reimprime tus compras y ventas.'], ['reportes','Reportes','◴','Analiza compras, ventas y margen en el período que necesites.'],
 ['materiales','Materiales','◇','Administra precios por kilogramo y niveles mínimos.','admin'], ['contactos','Clientes y proveedores','♧','Tu directorio comercial.','admin'],
 ['negocio','Mi negocio','⚙','Datos del negocio, impresora y preferencias.','admin'], ['usuarios','Usuarios','♙','Acceso personal y permisos por rol.','admin'],
 ['respaldo','Respaldos','↻','Protege tus datos e importa existencias desde V15.','admin'], ['auditoria','Actividad','≡','Historial de cambios y operaciones administrativas.','admin'],
 ['ayuda','Guía de uso','?','Un flujo sencillo para tu trabajo diario.']
];
const freshDraft = () => ({ items:[], requestId:crypto.randomUUID(), selected:null, category:'Todos', search:'' });
let auth, data, page='inicio', renderEpoch=0, drafts={ purchase:freshDraft(), sale:freshDraft() }, reportFilters={}, lastReport, users=[], lastTicket, pending, legacyData, toastTimer;
const isAdmin = () => auth.user.role === 'admin';
const canOperate = () => auth.user.role !== 'viewer';
function date(value) { return value ? new Date(value).toLocaleString('es-MX', { timeZone:data?.business.timezone || 'America/Tijuana', dateStyle:'short', timeStyle:'short' }) : '—'; }
function button(label, action, extra='', style='secondary') { return `<button type="button" class="button ${style}" data-action="${action}" ${extra}>${label}</button>`; }
function empty(title, copy='') { return `<div class="empty"><strong>${esc(title)}</strong>${esc(copy)}</div>`; }
function kpi(title, value, note, accent=false) { return `<div class="kpi${accent?' accent':''}"><span>${esc(title)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`; }
function icon(name) {
 const paths={inicio:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',compras:'M18 5 6 17 M6 7v10h10',ventas:'M6 18 18 6 M8 6h10v10',inventario:'M3 4h18v16H3z M3 9h18 M8 4v16 M16 4v16',caja:'M3 5h18v14H3z M3 9h18 M7 14h3 M15 14h2',gastos:'M5 5h14v14H5z M8 9h8 M8 13h5 M15 17l4 4 4-4',tickets:'M6 3h12v18l-3-2-3 2-3-2-3 2z M9 7h6 M9 11h6 M9 15h4',reportes:'M4 20h16 M7 16v-5 M12 16V4 M17 16V8',materiales:'M12 3 3 12l9 9 9-9z M12 8v8 M8 12h8',contactos:'M16 20v-3a4 4 0 0 0-8 0v3 M12 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M19 11a3 3 0 0 1 2 3v4 M5 11a3 3 0 0 0-2 3v4',negocio:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',usuarios:'M5 21v-3a7 7 0 0 1 14 0v3 M12 10a4 4 0 1 0 0-8 4 4 0 0 0 0 8',respaldo:'M4 9a8 8 0 1 1 0 6 M4 3v6h6 M12 8v5l3 2',auditoria:'M4 6h16 M4 12h16 M4 18h16',ayuda:'M9 8a3 3 0 1 1 4 3c-1 .5-1 1-1 3 M12 18h.01'};
 return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.materiales}"/></svg>`;
}
function table(headers, rows) { return `<div class="tablewrap"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`; }
function notify(message, error=false) { clearTimeout(toastTimer); $('toast').textContent=message; $('toast').className='toast'+(error?' error':''); $('toast').hidden=false; toastTimer=setTimeout(()=>$('toast').hidden=true, error?12000:5000); }
function modal(title, html) { $('detailTitle').textContent=title; $('detailBody').innerHTML=html; if (!$('detailDialog').open) $('detailDialog').showModal(); }
function closeModal() { $('detailDialog').close(); $('detailBody').replaceChildren(); }
async function api(url, method='GET', body) {
 let response;
 try { response=await fetch(url,{ method, headers:{ 'Content-Type':'application/json', ...(method!=='GET'?{'X-CSRF-Token':auth?.nonce || ''}:{}) }, body:body===undefined?undefined:JSON.stringify(body) }); }
 catch { throw Error('No se recibió respuesta. Comprueba el historial antes de repetir una operación; el mismo carrito conserva su identificador para reintentar sin duplicar.'); }
 const value=await response.json();
 if (!response.ok) { const error=Error(value.error || 'No se pudo completar la operación.'); error.status=response.status; if(response.status===401 && auth?.user) { auth=await api('/api/session'); showAuth(); } throw error; }
 return value;
}
async function refresh() { data=await api('/api/state'); }
function showAuth() {
 ++renderEpoch;
 $('shell').hidden=true; $('auth').hidden=false; closeModal();
 const setup=auth.needsSetup;
 $('auth').innerHTML=`<div class="auth-card"><img src="/brand.svg" alt=""><div class="eyebrow">METALES-GV PRO</div><h1>${setup?'Tu nueva operación empieza aquí.':'Bienvenido de nuevo.'}</h1><p>${setup?'Crea tu cuenta de administrador. Tus datos se guardan en SQLite, en este equipo.':'Entra para continuar con tu negocio.'}</p><form data-form="${setup?'setup':'login'}">${setup?'<label>Nombre del negocio<input name="business" required maxlength="120" placeholder="Ej. Recicladora del Norte"></label>':''}<label>Usuario<input name="name" autocomplete="username" required maxlength="60" autofocus></label><label>Contraseña<input name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" ${setup?'minlength="10"':''} required maxlength="200"></label>${setup?'<p class="small">Usa al menos 10 caracteres. No hay contraseñas predeterminadas.</p>':''}<div id="authError" class="auth-error" hidden></div><button class="button primary full" type="submit">${setup?'Crear mi negocio':'Iniciar sesión'} →</button></form><div class="auth-foot">SQLite local · Sin suscripción · Operación sin Internet</div></div>`;
}
async function view(target=page) {
 ++renderEpoch;
 page=target; const info=modules.find(m=>m[0]===page) || modules[0]; page=info[0];
 if ((info[4]==='admin'&&!isAdmin()) || (!canOperate()&&['compras','ventas','caja','gastos'].includes(page))) page='inicio';
 const current=modules.find(m=>m[0]===page); location.hash=page;
 $('auth').hidden=true; $('shell').hidden=false;
 $('navigation').innerHTML=modules.filter(m=>(!m[4]||isAdmin())&&(canOperate()||!['compras','ventas','caja','gastos'].includes(m[0]))).map(m=>`<button class="navitem${page===m[0]?' active':''}" data-go="${m[0]}"><span class="navicon">${icon(m[0])}</span>${m[1]}</button>`).join('');
 $('businessName').textContent=data.business.name; $('account').textContent=auth.user.name+' · '+roles[auth.user.role];
 $('pageTitle').textContent=current[1]; $('pageSubtitle').textContent=current[3]; $('headingActions').innerHTML='';
 $('shiftBanner').innerHTML=data.shift?`<div class="shiftbar"><span class="status-dot"></span> Turno #${data.shift.id} abierto · ${esc(data.shift.user_name)} · ${date(data.shift.opened_at)}<button class="linkbutton" data-go="caja">Ver caja →</button></div>`:`<div class="shiftbar warn">○ Caja cerrada · Abre un turno para registrar operaciones.${canOperate()?'<button class="linkbutton" data-go="caja">Abrir turno →</button>':''}</div>`;
 $('updated').textContent='Actualizado '+date(new Date().toISOString()); $('sidebar').classList.remove('visible');
 const renderers={ inicio:home, compras:()=>operation('purchase'), ventas:()=>operation('sale'), inventario:inventory, caja:cash, gastos:expenses, tickets:tickets, reportes:reports, materiales:materials, contactos:contacts, negocio:business, usuarios:userView, respaldo:backups, auditoria:audit, ayuda:help };
 $('content').innerHTML='<div class="panel empty">Cargando información…</div>';
 await renderers[page]();
}
function txRows(rows) { return rows.map(t=>`<tr><td><button class="linkbutton" data-action="ticket" data-id="${t.id}">${t.kind==='sale'?'V':'C'}-${String(t.id).padStart(6,'0')}</button></td><td><span class="badge ${t.kind==='sale'?'blue':''}">${types[t.kind]}</span></td><td>${esc(t.counterpart||'Público general')}<div class="small">${date(t.date)}</div></td><td>${payments[t.payment]}</td><td class="num"><b>${money(t.total_cents)}</b></td><td>${t.status==='void'?'<span class="badge red">Cancelado</span>':'<span class="badge">Registrado</span>'}</td></tr>`); }
async function home() {
 const epoch=++renderEpoch;
 const r=await api(`/api/report?from=${data.today}&to=${data.today}`), stock=data.materials.reduce((a,m)=>a+m.stock_g,0), low=data.materials.filter(m=>m.active&&m.stock_g<=m.min_g);
 if(epoch!==renderEpoch)return;
 $('headingActions').innerHTML=button('↻ Actualizar','refresh');
 $('content').innerHTML=`<div class="kpis">${kpi('VENTAS DE HOY',money(r.sales),r.rows.filter(x=>x.kind==='sale'&&x.status==='posted').length+' ventas registradas',true)}${kpi('COMPRAS DE HOY',money(r.purchases),'Material recibido')}${kpi('INVENTARIO TOTAL',kg(stock)+' kg',data.materials.length+' materiales en catálogo')}${kpi('EFECTIVO EN CAJA',money(data.shift?.expected.mxn),data.shift?'Turno #'+data.shift.id:'Sin turno abierto')}</div>${canOperate()?`<div class="quick-grid"><button class="quick" data-go="compras"><span>${icon("compras")}</span><div><strong>Nueva compra</strong><small>Recibir y pagar materiales · F2</small></div></button><button class="quick" data-go="ventas"><span>${icon("ventas")}</span><div><strong>Nueva venta</strong><small>Vender por kilogramo · F3</small></div></button><button class="quick" data-go="caja"><span>${icon("caja")}</span><div><strong>Mi caja</strong><small>Apertura, movimientos y corte · F4</small></div></button></div>`:''}<div class="columns"><div class="panel"><div class="panel-head"><h2>Últimas operaciones</h2><button class="linkbutton" data-go="tickets">Ver todas →</button></div>${data.transactions.length?table(['Folio','Operación','Cliente / proveedor','Pago','Importe','Estado'],txRows(data.transactions.slice(0,6))):empty('Todo listo para comenzar','Agrega materiales, abre un turno y registra tu primera compra.')}</div><div class="panel"><div class="panel-head"><h2>Tu operación hoy</h2><span class="badge">${esc(data.today)}</span></div><div class="cart-item"><span>Margen bruto</span><b>${money(r.margin)}</b></div><div class="cart-item"><span>Gastos</span><b>${money(r.expenses)}</b></div><div class="cart-item"><span>Resultado operativo</span><b>${money(r.result)}</b></div><p class="small">Margen = ventas − costo promedio del material vendido. Los gastos se muestran por separado.</p><h3>Existencias por revisar</h3>${low.length?low.slice(0,5).map(m=>`<div class="cart-item"><span>${esc(m.name)}</span><span class="badge amber">${kg(m.stock_g)} kg</span></div>`).join(''):empty(data.materials.length?'Inventario sin alertas':'Sin catálogo todavía')}${isAdmin()&&!data.materials.length?button('Agregar primer material','new-material','','primary'):''}</div></div>`;
}
function operation(kind) {
 const d=drafts[kind], isSale=kind==='sale', m=data.materials.find(m=>m.id===d.selected), active=data.materials.filter(m=>m.active), categories=['Todos',...new Set(active.map(m=>m.category))];
 const filtered=active.filter(m=>(d.category==='Todos'||m.category===d.category)&&m.name.toLowerCase().includes(d.search.toLowerCase()));
 $('content').innerHTML=`<div class="split"><div class="stack"><div class="panel"><h2>1. Selecciona el material</h2><input id="materialSearch" aria-label="Buscar material" placeholder="Buscar por nombre…" value="${esc(d.search)}" data-kind="${kind}"><div class="chips">${categories.map(c=>`<button class="chip${c===d.category?' active':''}" data-action="category" data-value="${esc(c)}" data-kind="${kind}">${esc(c)}</button>`).join('')}</div><div class="materials">${filtered.map(m=>`<button class="material${d.selected===m.id?' selected':''}" data-action="select-material" data-id="${m.id}" data-kind="${kind}"><span class="material-icon">${icons[m.name]||'♻'}</span><strong>${esc(m.name)}</strong><small>${money(isSale?m.sale_cents:m.buy_cents)} / kg</small>${isSale?`<small>${kg(m.stock_g)} kg disponibles</small>`:''}</button>`).join('')}</div>${!active.length?empty('No hay materiales activos','El administrador puede crear el catálogo en Materiales.'):''}</div>${m?`<div class="panel"><h2>2. Captura el peso · ${esc(m.name)}</h2><form data-form="add-line" data-kind="${kind}"><div class="form-grid"><label>Peso bruto (kg)<input class="weight" id="grossKg" name="grossKg" type="number" min="0.001" max="10000000" step="0.001" required autofocus></label><label>Tara (kg)<input class="weight" id="tareKg" name="tareKg" type="number" min="0" step="0.001" value="0" required></label></div><div class="net">PESO NETO<strong id="netKg">0.000 kg</strong></div><label>Precio MXN por kg<input name="price" type="number" min="0.01" step="0.01" required value="${amount(isSale?m.sale_cents:m.buy_cents)}" ${isAdmin()?'':'readonly'}></label><button class="button primary full" type="submit">+ Agregar al ticket <span class="small">↵</span></button></form></div>`:''}</div><div class="panel"><div class="panel-head"><h2>3. Ticket de ${isSale?'venta':'compra'}</h2><span class="badge">${d.items.length} renglones</span></div>${d.items.length?d.items.map((i,index)=>`<div class="cart-item"><div><strong>${esc(i.name)}</strong><small>${kg(i.netG)} kg × ${money(i.priceCents)} / kg</small><small>Bruto ${kg(i.grossG)} − tara ${kg(i.tareG)} kg</small></div><b>${money(i.total)}</b><button class="iconbutton" data-action="remove-line" data-index="${index}" data-kind="${kind}" aria-label="Quitar ${esc(i.name)}">×</button></div>`).join(''):empty('Tu ticket está vacío','Selecciona un material y captura el peso.')}<div class="total"><span>TOTAL ${isSale?'A COBRAR':'A PAGAR'}</span><strong>${money(d.items.reduce((n,i)=>n+i.total,0))}</strong></div><form data-form="checkout" data-kind="${kind}"><label>${isSale?'Cliente':'Proveedor'} (opcional)<input name="counterpart" list="contactNames" maxlength="120" placeholder="Público general"></label><datalist id="contactNames">${data.contacts.filter(c=>c.kind==='both'||c.kind===(isSale?'customer':'supplier')).map(c=>`<option value="${esc(c.name)}"></option>`).join('')}</datalist><div class="form-grid"><label>Forma de pago<select name="payment" id="payment"><option value="cash">Efectivo MXN</option><option value="transfer">Transferencia</option>${isSale?'<option value="card">Tarjeta</option><option value="usd">Efectivo USD</option>':''}</select></label>${isSale?'<label id="tenderLabel">Recibido (MXN)<input name="tender" id="tender" type="number" min="0" step="0.01" placeholder="Captura lo recibido"></label>':''}</div>${isSale?`<p class="small" id="paymentInfo">El cambio en MXN se calcula al confirmar.</p>`:''}<label>Nota (opcional)<input name="note" maxlength="500"></label><button type="submit" class="button primary full" ${!d.items.length||!data.shift?'disabled':''}>Revisar ${isSale?'venta':'compra'} →</button>${d.items.length?button('Vaciar ticket','clear-cart',`data-kind="${kind}"`):''}</form></div></div>`;
 if(m) $('grossKg').focus();
}
function inventory() {
 $('headingActions').innerHTML=button('↻ Actualizar','refresh');
 $('content').innerHTML=`<div class="kpis">${kpi('EXISTENCIAS',kg(data.materials.reduce((s,m)=>s+m.stock_g,0))+' kg','Peso neto disponible',true)}${kpi('VALOR DEL INVENTARIO',money(data.materials.reduce((s,m)=>s+m.value_cents,0)),'Costo promedio ponderado')}${kpi('MATERIALES',data.materials.length,'Activos e históricos')}${kpi('BAJO MÍNIMO',data.materials.filter(m=>m.active&&m.stock_g<=m.min_g).length,'Materiales para revisar')}</div><div class="panel">${data.materials.length?table(['Material','Categoría','Existencias kg','Costo prom. / kg','Valor MXN','Mínimo kg','Acciones'],data.materials.map(m=>`<tr><td><b>${esc(m.name)}</b>${!m.active?' <span class="badge amber">Inactivo</span>':''}</td><td>${esc(m.category)}</td><td class="num"><b>${kg(m.stock_g)}</b></td><td class="num">${money(m.stock_g?Math.round(m.value_cents*1000/m.stock_g):0)}</td><td class="num">${money(m.value_cents)}</td><td class="num">${kg(m.min_g)}</td><td><div class="actions">${button('Kardex','kardex',`data-id="${m.id}"`,'small')}${isAdmin()?button('Ajustar','adjust',`data-id="${m.id}"`,'small'):''}</div></td></tr>`)):empty('Tu inventario aún no tiene materiales')}</div>`;
}
function materialForm(mid) {
 const m=data.materials.find(m=>m.id===mid);
 modal(m?'Editar material':'Nuevo material',`<form data-form="material" data-id="${m?.id||''}"><div class="form-grid"><label class="wide">Nombre<input name="name" list="commonMaterials" required maxlength="80" value="${esc(m?.name||'')}"></label><datalist id="commonMaterials">${common.map(x=>`<option>${esc(x)}</option>`).join('')}</datalist><label>Categoría<select name="category">${['Metal','Plástico','Papel','Otros',...[m?.category].filter(x=>x&&!['Metal','Plástico','Papel','Otros'].includes(x))].map(c=>`<option${m?.category===c?' selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Mínimo (kg)<input name="minKg" type="number" min="0" step="0.001" required value="${weight(m?.min_g)}"></label><label>Precio de compra / kg<input name="buyPrice" type="number" min="0" step="0.01" required value="${amount(m?.buy_cents)}"></label><label>Precio de venta / kg<input name="salePrice" type="number" min="0" step="0.01" required value="${amount(m?.sale_cents)}"></label>${m?`<label class="check wide"><input name="active" type="checkbox" ${m.active?'checked':''}> Material activo para operar</label>`:'<label class="wide">Existencia inicial (kg)<input name="initialKg" type="number" min="0" step="0.001" required value="0"></label>'}</div><p class="small">La existencia inicial se valora al precio de compra. Los cambios de precio no alteran tickets anteriores.</p><div class="dialogActions"><button class="button primary" type="submit">Guardar material</button></div></form>`);
}
function materials() {
 $('headingActions').innerHTML=button('+ Nuevo material','new-material','','primary');
 $('content').innerHTML=`<div class="panel">${data.materials.length?table(['Material','Categoría','Compra / kg','Venta / kg','Estado',''],data.materials.map(m=>`<tr><td><b>${esc(m.name)}</b></td><td>${esc(m.category)}</td><td>${money(m.buy_cents)}</td><td>${money(m.sale_cents)}</td><td><span class="badge${m.active?'':' amber'}">${m.active?'Activo':'Inactivo'}</span></td><td>${button('Editar','edit-material',`data-id="${m.id}"`,'small')}</td></tr>`)):empty('Crea tu catálogo','Empieza con cobre, fierro, aluminio, PET, cartón u otros materiales.')}</div>`;
}
function cash() {
 const s=data.shift;
 $('content').innerHTML=s?`<div class="kpis">${kpi('EFECTIVO ESPERADO MXN',money(s.expected.mxn),'Fondo + entradas − salidas',true)}${kpi('EFECTIVO ESPERADO USD','USD '+amount(s.expected.usd),'Los dólares se cuentan por separado')}${kpi('FONDO INICIAL',money(s.opening_mxn),'Más USD '+amount(s.opening_usd))}${kpi('TIPO DE CAMBIO',number(s.rate/10000,4),'MXN por USD · Fijado al abrir')}</div><div class="two"><div class="panel"><h2>Movimientos de efectivo</h2><p class="small">Las compras en efectivo se descuentan de caja. Las transferencias no afectan el efectivo.</p><div class="actions">${button('+ Entrada','cash-entry','','primary')}${button('− Retiro','cash-withdrawal')}${button('Registrar gasto','go-expense')}${button('Cerrar turno','close-shift','','danger')}</div></div><div class="panel"><h2>Turno #${s.id}</h2><p>${esc(s.user_name)} · ${date(s.opened_at)}</p><p class="small">Solo el usuario que abrió el turno o un administrador puede operar esta caja.</p></div></div><div class="panel"><h2>Movimientos de este turno</h2>${cashTable(data.cashMoves)}</div>${cutHistory()}`:`<div class="two"><div class="panel"><h2>Abrir turno de caja</h2><p class="small">Cuenta el fondo inicial y captura el tipo de cambio que utilizarás durante este turno.</p><form data-form="open-shift"><div class="form-grid"><label>Fondo inicial MXN<input name="openingMxn" type="number" min="0" step="0.01" required value="0"></label><label>Fondo inicial USD<input name="openingUsd" type="number" min="0" step="0.01" required value="0"></label><label class="wide">Tipo de cambio manual (MXN por USD)<input name="rate" type="number" min="0.0001" step="0.0001" required placeholder="Ej. 19.50"></label></div><button type="submit" class="button primary full">Abrir turno</button></form></div><div class="panel"><h2>Empieza con una caja clara.</h2><p class="small">El fondo inicial no es una venta. Toda compra, venta, gasto y retiro queda asociado al turno y a su usuario.</p><p class="small">El tipo de cambio es manual; no se consulta ninguna cotización externa.</p></div></div>${cutHistory()}`;
}
