function help() {
 const steps=[['Prepara tu negocio','Configura el nombre, la zona horaria y los datos del ticket en Mi negocio. Crea usuarios personales.','negocio'],['Crea el catálogo','Agrega materiales con precio de compra y venta por kilogramo. Captura existencias iniciales solo al comenzar.','materiales'],['Abre la caja','Cuenta el fondo y captura el tipo de cambio manual. Solo puede existir un turno abierto.','caja'],['Compra y vende','Selecciona materiales, captura peso bruto y tara, agrega renglones y revisa el pago antes de registrar.','compras'],['Cierra y respalda','Revisa los movimientos, captura el dinero contado por moneda, imprime el corte y guarda una copia fuera del equipo.','respaldo']];
 $('content').innerHTML=`<div class="two"><div class="panel"><h2>Tu primer día con METales-GV Pro</h2>${steps.map(([title,copy,target],i)=>`<div class="help-step"><span>${i+1}</span><div><b>${title}</b><p>${copy}</p>${(!['negocio','materiales','respaldo'].includes(target)||isAdmin())?`<button class="linkbutton" data-go="${target}">Ir al módulo →</button>`:''}</div></div>`).join('')}</div><div class="panel"><h2>Atajos de teclado</h2><p><kbd>F2</kbd> Compras</p><p><kbd>F3</kbd> Ventas</p><p><kbd>F4</kbd> Caja y turnos</p><p><kbd>Enter</kbd> Agregar peso al ticket</p><p><kbd>Esc</kbd> Cerrar diálogo</p><h3>Reglas que protegen tu operación</h3><p class="small">No se vende más material del disponible. Las compras y retiros no pueden dejar efectivo negativo. Las cancelaciones se permiten en el turno abierto y conservan su historial. Cambiar un precio nunca modifica tickets anteriores.</p><h3>Pesaje e impresión</h3><p class="small">Los pesos se capturan manualmente. Esta versión no lee una báscula serial/USB. Instala tu impresora en Windows y valida una prueba en 58 u 80 mm.</p></div></div>`;
}
async function print(text,business=data.business) {
 if(window.pc) {
  if(!business.printerName) throw Error('Configura una impresora en Mi negocio. La operación ya está guardada.');
  const result=await window.pc.print({ text, printerName:business.printerName, paper:business.paper, mode:business.printMode, cut:business.autoCut });
  if(!result.success) throw Error(result.error||'No se pudo imprimir. Comprueba la cola antes de reimprimir.'); notify('Trabajo enviado a la impresora.');
 } else { const pre=document.createElement('pre'); pre.textContent=text; $('printArea').replaceChildren(pre); $('printArea').style.setProperty('--ticket-width',business.paper==='58mm'?'58mm':'80mm'); window.print(); }
}
function downloadText(text,filename) { const url=URL.createObjectURL(new Blob([text],{ type:'text/plain;charset=utf-8' })), a=document.createElement('a'); a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
async function fileValue(form,limit=24*1024*1024) { const file=form.elements.file.files[0]; if(!file||file.size>limit) throw Error('Selecciona un archivo de hasta 24 MB.'); return file; }
async function saved(message) { closeModal(); await refresh(); await view(); notify(message); }
document.addEventListener('submit',async event=>{
 const form=event.target.closest('[data-form]'); if(!form)return; event.preventDefault();
 const submit=form.querySelector('[type="submit"]'); if(submit?.disabled)return; if(submit)submit.disabled=true;
 const b=Object.fromEntries(new FormData(form)), name=form.dataset.form;
 try {
  if(name==='setup'||name==='login') { const r=await api('/api/'+name,'POST',b);auth={...auth,...r,needsSetup:false};await refresh();await view('inicio'); }
  else if(name==='material') { b.active=form.elements.active?.checked ?? true;await api('/api/materials'+(form.dataset.id?'/'+form.dataset.id:''),form.dataset.id?'PUT':'POST',b);await saved('Material guardado.'); }
  else if(name==='add-line') {
   const kind=form.dataset.kind,d=drafts[kind],m=data.materials.find(m=>m.id===d.selected);
   const g=Math.round(Number(b.grossKg)*1000),t=Math.round(Number(b.tareKg)*1000),p=Math.round(Number(b.price)*100);
   if(!m||g<=t||p<=0||!Number.isSafeInteger(g)||g>1e10||p>1e11||t<0)throw Error('Revisa el peso bruto, tara y precio.');
   const net=g-t,total=Number((BigInt(net)*BigInt(p)+500n)/1000n); if(total<=0)throw Error('El importe del renglón redondea a cero.');
   if(kind==='sale'&&d.items.filter(i=>i.materialId===m.id).reduce((n,i)=>n+i.netG,0)+net>m.stock_g)throw Error('No hay existencias suficientes para esa venta.');
   d.items.push({materialId:m.id,name:m.name,grossKg:b.grossKg,tareKg:b.tareKg,price:b.price,grossG:g,tareG:t,netG:net,priceCents:p,total});d.selected=null;operation(kind);
  } else if(name==='checkout') {
   const d=drafts[form.dataset.kind];if(!d.items.length)throw Error('Agrega material al ticket.');
   pending={kind:form.dataset.kind,requestId:d.requestId,items:d.items.map(({materialId,grossKg,tareKg,price})=>({materialId,grossKg,tareKg,price})),...b};
   const total=d.items.reduce((n,i)=>n+i.total,0),tender=Math.round(Number(b.tender||0)*100),equiv=b.payment==='usd'?Number((BigInt(tender)*BigInt(data.shift.rate)+5000n)/10000n):tender;
   if(pending.kind==='sale'&&['cash','usd'].includes(b.payment)&&equiv<total)throw Error('El importe recibido no cubre el total.');
   modal('Revisar '+(pending.kind==='sale'?'venta':'compra'),`${table(['Material','Peso neto','Precio / kg','Importe'],d.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${kg(i.netG)} kg</td><td>${money(i.priceCents)}</td><td>${money(i.total)}</td></tr>`))}<div class="total"><span>TOTAL MXN</span><strong>${money(total)}</strong></div><p>Pago: <b>${payments[b.payment]}</b></p>${pending.kind==='sale'&&['cash','usd'].includes(b.payment)?`<p>Recibido: ${b.payment==='usd'?'USD ':''}${money(tender)} · Cambio MXN: <b>${money(equiv-total)}</b></p>`:''}<p class="small">${esc(b.counterpart||'Público general')}${b.note?' · '+esc(b.note):''}</p><div class="dialogActions">${button('Volver','close')}${button('Registrar '+(pending.kind==='sale'?'venta':'compra'),'commit','','primary')}</div>`);
  } else if(name==='open-shift') {await api('/api/shifts/open','POST',b);await saved('Turno abierto.');}
  else if(name==='close-shift') {const r=await api('/api/shifts/close','POST',b);await saved(r.warning||'Turno cerrado y respaldado.');await showCut(r.id);}
  else if(name==='cash-move'||name==='expense') {await api('/api/cash','POST',{...b,type:name==='expense'?'expense':form.dataset.type});await saved('Movimiento registrado.');}
  else if(name==='adjust') {await api('/api/stock/adjust','POST',{...b,materialId:form.dataset.id});await saved('Ajuste de inventario registrado.');}
  else if(name==='void') {await api('/api/transactions/'+form.dataset.id+'/void','POST',b);await refresh();await view();await showTicket(form.dataset.id);notify('Operación cancelada con movimientos de reversa.');}
  else if(name==='report') {reportFilters=b;await reports();}
  else if(name==='contact') {await api('/api/contacts','POST',b);await saved('Contacto guardado.');}
  else if(name==='business') {b.autoPrint=form.elements.autoPrint.checked;b.autoCut=form.elements.autoCut.checked;await api('/api/business','PUT',b);await saved('Configuración guardada.');}
  else if(name==='user') {if(form.dataset.id)b.active=form.elements.active.checked;await api('/api/users'+(form.dataset.id?'/'+form.dataset.id:''),form.dataset.id?'PATCH':'POST',b);await saved('Usuario guardado.');}
  else if(name==='password') {const r=await api('/api/password','PUT',b);auth.nonce=r.nonce;closeModal();notify('Contraseña actualizada.');}
  else if(name==='restore') {const file=await fileValue(form),bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const r=await api('/api/restore','POST',{base64:btoa(binary),confirm:b.confirm});notify(r.message);auth=await api('/api/session');showAuth();}
  else if(name==='legacy-preview') {const file=await fileValue(form);let parsed;try{parsed=JSON.parse(await file.text());}catch{throw Error('JSON no válido.');}const r=await api('/api/legacy/preview','POST',{data:parsed});legacyData={data:parsed,filename:file.name};modal('Importar existencias de V15',`<div class="notice">${r.counts.materials} materiales · ${r.counts.purchases} compras y ${r.counts.sales} ventas en el archivo original.</div>${table(['Material','Existencia kg','Compra / kg'],r.materials.map(m=>`<tr><td>${esc(m.name)}</td><td>${kg(m.stock)}</td><td>${money(m.buy)}</td></tr>`))}<p class="small">Se importarán catálogo y saldos iniciales. El historial se archiva como JSON original, sin crear tickets nuevos ni reutilizar PIN.</p><form data-form="legacy-import"><label>Escribe IMPORTAR<input name="confirm" pattern="IMPORTAR" required></label><button type="submit" class="button primary">Importar catálogo y saldos</button></form>`);}
  else if(name==='legacy-import') {await api('/api/legacy/import','POST',{...legacyData,confirm:b.confirm});legacyData=null;await saved('Catálogo y existencias importados. Original archivado.');}
 } catch(error) { if(name==='login'||name==='setup') {if($('authError')){$('authError').textContent=error.message;$('authError').hidden=false;}} else notify(error.message,true); }
 finally { if(submit?.isConnected)submit.disabled=false; }
});
async function showCut(id) { const r=await api('/api/cuts/'+id);lastTicket={...r,id:null};modal('Corte de caja #'+id,`<pre class="ticket">${esc(r.text)}</pre><div class="actions">${button('Imprimir corte','print-ticket','','primary')}${button('Descargar TXT','download-ticket')}</div>`); }
document.addEventListener('click',async event=>{
 const go=event.target.closest('[data-go]'); if(go){await view(go.dataset.go).catch(e=>notify(e.message,true));return;}
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action,mid=Number(el.dataset.id);
 el.disabled=true;
 try {
  if(a==='close')closeModal();
  else if(a==='menu')$('sidebar').classList.toggle('visible');
  else if(a==='refresh'){await refresh();await view();}
  else if(a==='logout'){if((drafts.purchase.items.length||drafts.sale.items.length)&&!confirm('Hay tickets sin registrar. ¿Salir y descartarlos?'))return;await api('/api/logout','POST',{});drafts={purchase:freshDraft(),sale:freshDraft()};auth=await api('/api/session');showAuth();}
  else if(a==='password')modal('Cambiar mi contraseña','<form data-form="password"><label>Contraseña actual<input name="current" type="password" required autocomplete="current-password"></label><label>Nueva contraseña<input name="password" type="password" required minlength="10" maxlength="200" autocomplete="new-password"></label><button class="button primary" type="submit">Cambiar contraseña</button></form>');
  else if(a==='new-material'||a==='edit-material')materialForm(a==='new-material'?null:mid);
  else if(a==='select-material'){drafts[el.dataset.kind].selected=mid;operation(el.dataset.kind);}
  else if(a==='category'){drafts[el.dataset.kind].category=el.dataset.value;operation(el.dataset.kind);}
  else if(a==='remove-line'){drafts[el.dataset.kind].items.splice(Number(el.dataset.index),1);operation(el.dataset.kind);}
  else if(a==='clear-cart'){if(confirm('¿Vaciar este ticket sin registrar?')){drafts[el.dataset.kind]=freshDraft();operation(el.dataset.kind);}}
  else if(a==='commit') {
   if(!pending)throw Error('No hay una operación pendiente.');
   const t=await api('/api/transactions','POST',pending);drafts[pending.kind]=freshDraft();pending=null;await refresh();await view();await showTicket(t.id);notify('Operación '+t.folio+' guardada.');
   if(data.business.autoPrint)try{await print(lastTicket.text);}catch(e){notify('Operación guardada. '+e.message,true);}
  }
  else if(a==='ticket')await showTicket(mid);
  else if(a==='print-ticket')await print(lastTicket.text);
  else if(a==='download-ticket')downloadText(lastTicket.text,(lastTicket.folio||'corte-de-caja')+'.txt');
  else if(a==='void-ticket')modal('Cancelar operación',`<div class="notice">Se revertirán el inventario y el efectivo. El ticket y el motivo se conservan.</div><form data-form="void" data-id="${mid}"><label>Motivo<input name="reason" required maxlength="400"></label><button type="submit" class="button danger">Confirmar cancelación</button></form>`);
  else if(a==='adjust')modal('Ajustar inventario · '+data.materials.find(m=>m.id===mid).name,`<form data-form="adjust" data-id="${mid}"><label>Diferencia en kg (negativo para salida)<input name="deltaKg" type="number" step="0.001" required placeholder="Ej. -2.500"></label><label>Motivo<input name="reason" required maxlength="400"></label><button type="submit" class="button primary">Registrar ajuste</button></form>`);
  else if(a==='kardex'){const rows=await api('/api/stock/moves?materialId='+mid);modal('Kardex · '+data.materials.find(m=>m.id===mid).name,table(['Fecha','Movimiento','Entrada / salida kg','Saldo kg','Motivo','Usuario'],rows.map(r=>`<tr><td>${date(r.date)}</td><td>${types[r.type]||esc(r.type)}</td><td>${kg(r.delta_g)}</td><td>${kg(r.after_g)}</td><td>${esc(r.reason)}</td><td>${esc(r.user_name)}</td></tr>`)));}
  else if(a==='cash-entry'||a==='cash-withdrawal')modal(a==='cash-entry'?'Entrada de efectivo':'Retiro de efectivo',`<form data-form="cash-move" data-type="${a==='cash-entry'?'entry':'withdrawal'}"><label>Importe MXN<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Motivo<input name="reason" required maxlength="400"></label><button type="submit" class="button primary">Registrar movimiento</button></form>`);
  else if(a==='go-expense')await view('gastos');
  else if(a==='close-shift'){const s=data.shift;modal('Cerrar turno #'+s.id,`<div class="notice">Esperado: <b>${money(s.expected.mxn)} MXN</b> y <b>USD ${amount(s.expected.usd)}</b>. Cuenta el dinero físico; la diferencia se conserva en el corte.</div><form data-form="close-shift"><div class="form-grid"><label>Efectivo contado MXN<input name="countedMxn" type="number" min="0" step="0.01" required></label><label>Efectivo contado USD<input name="countedUsd" type="number" min="0" step="0.01" required value="0"></label></div><label>Observación<input name="note" maxlength="500"></label><button type="submit" class="button primary">Confirmar corte y cerrar turno</button></form>`);}
  else if(a==='cut')await showCut(mid);
  else if(a==='csv')location.href='/api/report.csv?'+new URLSearchParams(reportFilters);
  else if(a==='report-today'){reportFilters={from:data.today,to:data.today};await reports();}
  else if(a==='new-contact')modal('Nuevo contacto','<form data-form="contact"><label>Nombre<input name="name" required maxlength="120"></label><label>Tipo<select name="kind" aria-label="Tipo"><option value="supplier">Proveedor</option><option value="customer">Cliente</option><option value="both">Cliente y proveedor</option></select></label><label>Teléfono<input name="phone" maxlength="60"></label><label>RFC<input name="taxId" maxlength="40"></label><button class="button primary" type="submit">Guardar contacto</button></form>');
  else if(a==='new-user'||a==='edit-user')userForm(a==='new-user'?null:mid);
  else if(a==='list-printers'){const printers=await window.pc.listPrinters();$('printerNames').innerHTML='<option value="">Seleccionar impresora</option>'+printers.map(p=>`<option value="${esc(p.name)}" ${p.name===data.business.printerName?'selected':''}>${esc(p.displayName||p.name)}</option>`).join('');notify(printers.length+' impresoras encontradas.');}
  else if(a==='printer-settings')await window.pc.openPrintersSettings();
  else if(a==='test-print')await print(data.business.name+'\nTICKET DE PRUEBA\nMETales-GV Pro\n'+date(new Date().toISOString())+'\n0123456789\n------------------------\n10.000 kg x $5.00 = $50.00\nSin movimiento de caja o inventario.');
 }catch(error){notify(error.message,true);}finally{if(el.isConnected)el.disabled=false;}
});
document.addEventListener('input',event=>{
 if(['grossKg','tareKg'].includes(event.target.id))$('netKg').textContent=number(Math.max(0,Number($('grossKg').value||0)-Number($('tareKg').value||0)))+' kg';
 if(event.target.id==='materialSearch'){const d=drafts[event.target.dataset.kind],position=event.target.selectionStart;d.search=event.target.value;operation(event.target.dataset.kind);$('materialSearch').focus();$('materialSearch').setSelectionRange(position,position);}
 if(event.target.id==='ticketSearch'){const q=event.target.value.toLowerCase();const rows=data.transactions.filter(t=>(String(t.id)+' '+String(t.id).padStart(6,'0')+' '+t.counterpart+' '+t.user_name).toLowerCase().includes(q));$('ticketList').innerHTML=table(['Folio','Operación','Cliente / proveedor','Pago','Importe','Estado'],txRows(rows));}
});
document.addEventListener('change',event=>{
 if(event.target.id==='payment'&&$('tender')){const p=event.target.value,show=['cash','usd'].includes(p);$('tenderLabel').hidden=!show;$('tender').required=show;$('tender').value='';$('tenderLabel').firstChild.textContent=p==='usd'?'Recibido (USD)':'Recibido (MXN)';$('paymentInfo').textContent=p==='usd'?'Tipo de cambio del turno: '+number(data.shift?.rate/10000,4)+' MXN/USD. Cambio en pesos.':p==='cash'?'El cambio se entrega en pesos.':'No afecta el efectivo de caja.';}
});
document.addEventListener('keydown',event=>{if(!auth?.user||$('detailDialog').open)return;const map={F2:'compras',F3:'ventas',F4:'caja'};if(map[event.key]&&canOperate()){event.preventDefault();view(map[event.key]).catch(e=>notify(e.message,true));}});
window.addEventListener('beforeunload',event=>{if(drafts.purchase.items.length||drafts.sale.items.length){event.preventDefault();event.returnValue='';}});
window.addEventListener('hashchange',()=>{if(auth?.user&&location.hash.slice(1)!==page)view(location.hash.slice(1)).catch(e=>notify(e.message,true));});
$('detailDialog').addEventListener('close',()=>{if(!$('detailDialog').open)$('detailBody').replaceChildren();});
async function init(){try{auth=await api('/api/session');if(auth.user){await refresh();await view(location.hash.slice(1)||'inicio');}else showAuth();}catch(e){$('auth').hidden=false;$('auth').innerHTML=`<div class="auth-card"><h1>No se pudo iniciar.</h1><p>${esc(e.message)}</p><p>Recarga para volver a conectar al servicio local.</p></div>`;}}
init();
